using ElitePos.LocalService.Models;
using ElitePos.LocalService.Services;

namespace ElitePos.LocalService.Endpoints;
public static class PurchaseEndpoints
{
    public static IEndpointRouteBuilder MapPurchaseEndpoints(this IEndpointRouteBuilder endpoints){var group=endpoints.MapGroup("/api/purchases"); group.MapGet("",async(PurchaseService service,CancellationToken ct)=>Results.Ok(await service.GetAsync(ct))); group.MapGet("/{id:long}",async(long id,PurchaseService service,CancellationToken ct)=>{var item=await service.GetByIdAsync(id,ct); return item is null?Results.NotFound():Results.Ok(item);}); group.MapGet("/{id:long}/costs",async(long id,PurchaseService service,CancellationToken ct)=>Results.Ok(await service.GetCostsAsync(id,ct))); group.MapPost("/{id:long}/costs",async(long id,PurchaseAdditionalCostWriteRequest request,PurchaseService service,CancellationToken ct)=>{try{return Results.Created($"/api/purchases/{id}/costs",await service.AddCostAsync(id,request,ct));}catch(PurchaseException ex){return Results.Problem(ex.Message,statusCode:ex.StatusCode);}}); group.MapPatch("/{purchaseId:long}/lines/{lineId:long}",async(long purchaseId,long lineId,PurchaseLineMetadataUpdateRequest request,PurchaseService service,CancellationToken ct)=>{try{return await service.UpdateLineMetadataAsync(purchaseId,lineId,request,ct)?Results.NoContent():Results.NotFound();}catch(PurchaseException ex){return Results.Problem(ex.Message,statusCode:ex.StatusCode);}}); group.MapPost("",async(PurchaseWriteRequest request,PurchaseService service,CancellationToken ct)=>{try{return Results.Created("/api/purchases",await service.SaveAsync(request,ct));}catch(PurchaseException ex){return Results.Problem(ex.Message,statusCode:ex.StatusCode);}}); group.MapPost("/{id:long}/confirm",async(long id,PurchaseService service,CancellationToken ct)=>{try{var item=await service.PostDraftAsync(id,ct);return item is null?Results.NotFound():Results.Ok(item);}catch(PurchaseException ex){return Results.Problem(ex.Message,statusCode:ex.StatusCode);}}); group.MapDelete("/{id:long}",async(long id,PurchaseService service,CancellationToken ct)=>Results.Ok(new{deleted=await service.DeleteDraftAsync(id,ct)})); return endpoints;}
}
